<?php
require_once __DIR__ . '/inc/bootstrap.php';
require_once __DIR__ . '/inc/public_contact.php';
require_login();
$pdo=db(); $user=current_user();
if(!tickex_is_super_admin($user)) abort_404('No tenés permiso.');
tickex_public_contact_ensure_schema($pdo);
$statuses=tickex_public_contact_statuses(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!tickex_csrf_verify(isset($_POST['_csrf'])?(string)$_POST['_csrf']:''))$error='La sesión venció.';
 else{$id=isset($_POST['id'])?(int)$_POST['id']:0;$status=isset($_POST['status'])?(string)$_POST['status']:'';if($id>0&&isset($statuses[$status])){$st=$pdo->prepare("UPDATE public_contact_requests SET status=:status,updated_at=datetime('now') WHERE id=:id");$st->execute(array(':status'=>$status,':id'=>$id));header('Location: superadmin_contactos.php?id='.$id);exit;}else $error='Estado inválido.';}
}
$filter=isset($_GET['status'])?(string)$_GET['status']:'';if($filter!==''&&!isset($statuses[$filter]))$filter='';
$sql='SELECT * FROM public_contact_requests'.($filter!==''?' WHERE status=:status':'').' ORDER BY CASE status WHEN \'new\' THEN 1 WHEN \'contacted\' THEN 2 ELSE 3 END,datetime(created_at) DESC LIMIT 300';$st=$pdo->prepare($sql);$st->execute($filter!==''?array(':status'=>$filter):array());$rows=$st->fetchAll(PDO::FETCH_ASSOC);
$selected=null;$selectedId=isset($_GET['id'])?(int)$_GET['id']:0;if($selectedId){$st=$pdo->prepare('SELECT * FROM public_contact_requests WHERE id=:id');$st->execute(array(':id'=>$selectedId));$selected=$st->fetch(PDO::FETCH_ASSOC);}
$counts=array('new'=>0,'contacted'=>0,'closed'=>0);foreach($pdo->query('SELECT status,COUNT(*) total FROM public_contact_requests GROUP BY status')->fetchAll(PDO::FETCH_ASSOC) as $row)if(isset($counts[$row['status']]))$counts[$row['status']]=(int)$row['total'];
$csrf=tickex_csrf_token();$title='Consultas comerciales';include __DIR__.'/inc/layout_top.php';
?><style>.lead-shell{max-width:1120px;margin:auto;display:grid;gap:16px}.lead-hero{padding:26px;background:linear-gradient(135deg,#151b35,#342365)}.lead-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:17px}.lead-stat{padding:13px;border:1px solid var(--line);border-radius:13px;background:rgba(0,0,0,.18)}.lead-stat span{display:block;color:var(--muted);font-size:11px}.lead-stat strong{font-size:25px}.lead-filter,.lead-head,.lead-actions{display:flex;gap:9px;align-items:center;justify-content:space-between;flex-wrap:wrap}.lead-list{display:grid;gap:8px;margin-top:15px}.lead-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;padding:14px;border:1px solid var(--line);border-radius:13px;color:inherit;text-decoration:none}.lead-row:hover{border-color:#745be8}.lead-row small,.lead-meta{color:var(--muted)}.lead-badge{padding:5px 8px;border:1px solid var(--line);border-radius:999px;font-size:10px;font-weight:850;text-transform:uppercase}.lead-message{white-space:pre-wrap;padding:15px;border:1px solid var(--line);border-radius:13px;background:rgba(255,255,255,.025)}@media(max-width:600px){.lead-stats{grid-template-columns:1fr}.lead-row{grid-template-columns:1fr}}</style><main class="lead-shell"><section class="card lead-hero"><div class="muted">CRECIMIENTO</div><h1>Consultas comerciales</h1><p class="muted">Personas que quieren conocer o empezar a usar Tickex.</p><div class="lead-stats"><div class="lead-stat"><span>Nuevas</span><strong><?php echo $counts['new'];?></strong></div><div class="lead-stat"><span>Contactadas</span><strong><?php echo $counts['contacted'];?></strong></div><div class="lead-stat"><span>Cerradas</span><strong><?php echo $counts['closed'];?></strong></div></div></section><?php if($error!==''):?><div class="flash err"><?php echo e($error);?></div><?php endif;?><?php if($selected):?><section class="card"><div class="lead-head"><div><a href="superadmin_contactos.php">← Volver</a><h2><?php echo e($selected['name']);?></h2><div class="lead-meta"><?php echo e($selected['public_id']);?> · <?php echo e($selected['created_at']);?></div></div><span class="lead-badge"><?php echo e($statuses[$selected['status']]);?></span></div><p><strong>Email:</strong> <a href="mailto:<?php echo e($selected['email']);?>"><?php echo e($selected['email']);?></a><?php if($selected['phone']!==''):?> · <strong>Teléfono:</strong> <?php echo e($selected['phone']);?><?php endif;?></p><p><strong>Organización:</strong> <?php echo e($selected['organization']?:'Sin indicar');?> · <strong>Evento:</strong> <?php echo e($selected['event_type']?:'Sin indicar');?></p><div class="lead-message"><?php echo e($selected['message']);?></div><form method="post" class="lead-actions" style="margin-top:15px"><input type="hidden" name="_csrf" value="<?php echo e($csrf);?>"><input type="hidden" name="id" value="<?php echo (int)$selected['id'];?>"><label>Estado <select name="status"><?php foreach($statuses as $key=>$label):?><option value="<?php echo e($key);?>"<?php echo $selected['status']===$key?' selected':'';?>><?php echo e($label);?></option><?php endforeach;?></select></label><button class="btn" type="submit">Guardar</button></form></section><?php else:?><section class="card"><form method="get" class="lead-filter"><label>Estado <select name="status"><option value="">Todos</option><?php foreach($statuses as $key=>$label):?><option value="<?php echo e($key);?>"<?php echo $filter===$key?' selected':'';?>><?php echo e($label);?></option><?php endforeach;?></select></label><button class="btn" type="submit">Filtrar</button></form><div class="lead-list"><?php if(!$rows):?><p class="muted">No hay consultas con este filtro.</p><?php endif;?><?php foreach($rows as $row):?><a class="lead-row" href="superadmin_contactos.php?id=<?php echo (int)$row['id'];?>"><div><small><?php echo e($row['public_id']);?> · <?php echo e($row['created_at']);?></small><h3><?php echo e($row['name']);?> · <?php echo e($row['organization']?:$row['email']);?></h3><div class="lead-meta"><?php echo e($row['event_type']?:'Tipo de evento sin indicar');?></div></div><span class="lead-badge"><?php echo e($statuses[$row['status']]);?></span></a><?php endforeach;?></div></section><?php endif;?></main><?php include __DIR__.'/inc/layout_bottom.php';?>

